To help you find a suitable hotel in London, I'll use the `get_all_hotels_in_city` function to retrieve all hotels in the city. Then, I'll apply a filter to select hotels with a rating of at least 4.0 and a price range within your budget of 160. After that, I'll sort the results by the quality assurance score in descending order to prioritize higher QA scores.

Here's the call:

```json
{
  "function": "apply_filter_and_sort",
  "arguments": {
    "hotels": {
      "function": "get_all_hotels_in_city",
      "arguments": {
        "city": "London"
      }
    },
    "filtered_hotels": {
      "function": "filter_hotels",
      "arguments": {
        "hotels": {
          "function": "get_all_hotels_in_city",
          "arguments": {
            "city": "London"
          }
        },
        "rating": {
          "minimum": 4.0
        },
        "price_range": {
          "maximum": 160.00
        }
      }
    },
    "sorted_hotels": {
      "function": "sort_hotels",
      "arguments": {
        "hotels": "filtered_hotels",
        "criteria": {
          "qa_score": {
            "direction": "desc"
          }
        }
      }
    }
  }
}
```

